using System.Linq.Expressions;

namespace InvoiceService.Domain.Invoices;

public sealed class Invoice
{
    /// <summary>Generated by the service from a database sequence, e.g. FTR-000001. Primary key.</summary>
    public required string InvoiceNumber { get; set; }

    public required string CustomerCode { get; set; }

    public decimal Amount { get; set; }

    public required string Currency { get; set; }

    public DateOnly InvoiceDate { get; set; }

    /// <summary>One of <see cref="InvoiceStatus"/>, enforced by a check constraint.</summary>
    public required string Status { get; set; }

    /// <summary>Reference returned by the ERP on 202; null while the invoice is not sent.</summary>
    public string? ErpReference { get; set; }

    /// <summary>The ERP's reason from an invoice.rejected event; null unless the invoice is Reddedildi.</summary>
    public string? RejectReason { get; set; }

    /// <summary>Description of the error from the last send; null after a successful send.</summary>
    public string? LastError { get; set; }

    /// <summary>Attempts to get the invoice to the ERP over its whole life, resends included (never reset).</summary>
    public int SendAttemptCount { get; set; }

    public DateTimeOffset CreatedAt { get; set; }

    public DateTimeOffset UpdatedAt { get; set; }

    /// <summary>When the reconciliation last asked the ERP about this invoice; null if it never has. Writing it does
    /// not change <see cref="UpdatedAt"/>.</summary>
    public DateTimeOffset? ErpCheckedAt { get; set; }

    /// <summary>What the ERP answered then, one of <see cref="ErpCheckResult"/>.</summary>
    public string? ErpCheckResult { get; set; }
}

/// <summary>
/// Stuck: Gönderildi or İşleme Alındı and not changed since <c>cutoff</c> (now minus Reconciliation:StuckAfterMinutes).
/// One expression for the database filter, the summary's count and the flag on each invoice, so they cannot disagree.
/// </summary>
public static class StuckInvoice
{
    public static Expression<Func<Invoice, bool>> Before(DateTimeOffset cutoff) =>
        i => (i.Status == InvoiceStatus.Sent || i.Status == InvoiceStatus.Processing) && i.UpdatedAt < cutoff;
}

/// <summary>The ERP's answer as the reconciliation records it on the invoice.</summary>
public static class ErpCheckResult
{
    public const string NotFound = "Kayıt yok";

    /// <param name="decision">The ERP's decision: none, received, approved, rejected or cancelled.</param>
    public static string Found(string decision) => $"Kayıtlı, karar: {decision}";
}

public static class InvoiceStatus
{
    /// <summary>Queued in erp_outbox, not sent to the ERP yet.</summary>
    public const string Pending = "Bekliyor";
    public const string Sent = "Gönderildi";

    /// <summary>The ERP reported invoice.received.</summary>
    public const string Processing = "İşleme Alındı";

    /// <summary>Final for decisions: the ERP reported invoice.approved; only the ERP's cancellation can change it.</summary>
    public const string Approved = "Onaylandı";

    /// <summary>Final: the ERP reported invoice.rejected (reason in reject_reason); no event can change it.</summary>
    public const string Rejected = "Reddedildi";

    /// <summary>Permanent: every attempt is used up (or the ERP rejected it); only a resend queues it again.</summary>
    public const string Failed = "Başarısız";

    /// <summary>Final: the cancellation is complete; no event or operation can change it.</summary>
    public const string Cancelled = "İptal Edildi";

    public static readonly string[] All = [Pending, Sent, Processing, Approved, Rejected, Failed, Cancelled];

    /// <summary>The statuses that mean the ERP has accepted the invoice.</summary>
    public static readonly string[] ErpHasIt = [Sent, Processing, Approved, Rejected];

    /// <summary>
    /// Reconciliation checks these however old they are: neither final nor waiting in the outbox, or (Onaylandı, İptal Edildi)
    /// a cancellation the two sides can disagree about. Reddedildi and Bekliyor have no such disagreement.
    /// </summary>
    public static readonly string[] CheckedAtAnyAge = [Sent, Processing, Failed, Approved, Cancelled];
}

public static class InvoiceNumber
{
    public const string Prefix = "FTR-";

    /// <summary>FTR-000001 ... FTR-999999; grows past six digits instead of being truncated.</summary>
    public static string Format(long sequenceValue) => $"{Prefix}{sequenceValue:D6}";
}
